insert into public.questions (id, kind, prompt, options, marks, image_url) values ('a02a73ad-f353-5a2d-a0cd-5a7faa5b13b6', 'short', 'Explain the roles of reproductive isolation and differential selection in speciation.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a02a73ad-f353-5a2d-a0cd-5a7faa5b13b6', 'Reproductive isolation stops gene flow between populations [1]; different selection pressures in their environments favour different alleles (differential selection) [1]; the populations diverge until they can no longer interbreed, becoming separate species [1].', 'Reproductive isolation stops gene flow between populations [1]; different selection pressures in their environments favour different alleles (differential selection) [1]; the populations diverge until they can no longer interbreed, becoming separate species [1].', '[{"text": "Marking point 1", "any": ["isolat", "no gene flow", "cannot interbreed"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["different selection", "different conditions", "differential", "different environments"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["diverge", "different", "new species", "cannot interbreed"], "all": [], "marks": 1}]'::jsonb, 'Reproductive isolation stops gene flow between populations [1]; different selection pressures in their environments favour different alleles (differential selection) [1]; the populations diverge until they can no longer interbreed, becoming separate species [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('c6bd2a01-0d3b-50fd-a9c9-d627a464d112', 'a02a73ad-f353-5a2d-a0cd-5a7faa5b13b6', 10);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('312182e8-ba64-5f68-abcb-e5564f86e0a5', 'short', 'Distinguish between homologous and analogous structures, with an example of each.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('312182e8-ba64-5f68-abcb-e5564f86e0a5', 'Homologous structures share a basic structure from a common ancestor but may differ in function [1]; analogous structures have similar functions but evolved separately by convergent evolution [1]; e.g. pentadactyl limbs (homologous) vs bird and insect wings (analogous) [1].', 'Homologous structures share a basic structure from a common ancestor but may differ in function [1]; analogous structures have similar functions but evolved separately by convergent evolution [1]; e.g. pentadactyl limbs (homologous) vs bird and insect wings (analogous) [1].', '[{"text": "Marking point 1", "any": ["common ancestor", "ancestry", "same structure"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["convergent", "different origin", "unrelated", "similar function"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["pentadactyl", "arm", "wing", "flipper", "insect"], "all": [], "marks": 1}]'::jsonb, 'Homologous structures share a basic structure from a common ancestor but may differ in function [1]; analogous structures have similar functions but evolved separately by convergent evolution [1]; e.g. pentadactyl limbs (homologous) vs bird and insect wings (analogous) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
