insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('99f923d7-b761-58f1-93a9-a54a7e8f4814', 'Base sequence comparisons/cladograms showed that the figwort family was not a single clade (members did not share one common ancestor exclusive to them) [1]; so it was split into several families and some genera moved, so that families correspond to clades [1].', 'Base sequence comparisons/cladograms showed that the figwort family was not a single clade (members did not share one common ancestor exclusive to them) [1]; so it was split into several families and some genera moved, so that families correspond to clades [1].', '[{"text": "Marking point 1", "any": ["dna", "sequence", "cladogram"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not a clade", "different ancestors", "not all", "split", "several families", "moved"], "all": [], "marks": 1}]'::jsonb, 'Base sequence comparisons/cladograms showed that the figwort family was not a single clade (members did not share one common ancestor exclusive to them) [1]; so it was split into several families and some genera moved, so that families correspond to clades [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
