insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4e5640b0-5091-5181-b6b6-d24a3a95b306', 'High biodiversity gives complex food webs with alternative food sources and pathways [1], so if one species declines others can take its place and the ecosystem is less disrupted [1].', 'High biodiversity gives complex food webs with alternative food sources and pathways [1], so if one species declines others can take its place and the ecosystem is less disrupted [1].', '[{"text": "Marking point 1", "any": ["food web", "alternative", "many species", "more interactions"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["if one", "loss", "decline", "recover", "less affected"], "all": [], "marks": 1}]'::jsonb, 'High biodiversity gives complex food webs with alternative food sources and pathways [1], so if one species declines others can take its place and the ecosystem is less disrupted [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
