insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('98b9d77e-7d24-5add-9681-d5389334a635', 'Fewer trees means less transpiration [1], so less rainfall and longer dry seasons [1]; more trees die and fires increase, a positive feedback that could turn rainforest into savanna irreversibly [1].', 'Fewer trees means less transpiration [1], so less rainfall and longer dry seasons [1]; more trees die and fires increase, a positive feedback that could turn rainforest into savanna irreversibly [1].', '[{"text": "Marking point 1", "any": ["transpiration", "less water vapour"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["rainfall", "drier", "drought"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["fire", "more trees die", "savanna", "positive feedback", "irreversible"], "all": [], "marks": 1}]'::jsonb, 'Fewer trees means less transpiration [1], so less rainfall and longer dry seasons [1]; more trees die and fires increase, a positive feedback that could turn rainforest into savanna irreversibly [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
