insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('79973b34-3fef-517d-9654-1899e9d5a7fa', 'Higher temperatures cause coral bleaching [1], as corals expel their zooxanthellae and lose their food supply [1]; CO₂ dissolving in seawater lowers pH (acidification), reducing carbonate for building skeletons [1].', 'Higher temperatures cause coral bleaching [1], as corals expel their zooxanthellae and lose their food supply [1]; CO₂ dissolving in seawater lowers pH (acidification), reducing carbonate for building skeletons [1].', '[{"text": "Marking point 1", "any": ["temperature", "warming", "bleaching"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["zooxanthellae", "algae", "expel"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["acidif", "ph", "carbonate", "skeleton"], "all": [], "marks": 1}]'::jsonb, 'Higher temperatures cause coral bleaching [1], as corals expel their zooxanthellae and lose their food supply [1]; CO₂ dissolving in seawater lowers pH (acidification), reducing carbonate for building skeletons [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
