insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('1ca10f05-ff40-559a-87e0-e479a7992979', 'Rewetting peatlands makes them waterlogged, anaerobic and acidic [1], which stops decomposition so dead plant matter accumulates as peat, storing carbon (a carbon sink) [1].', 'Rewetting peatlands makes them waterlogged, anaerobic and acidic [1], which stops decomposition so dead plant matter accumulates as peat, storing carbon (a carbon sink) [1].', '[{"text": "Marking point 1", "any": ["waterlogged", "rewet", "anaerobic", "acidic"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["decompos", "peat accumulat", "store carbon", "sink"], "all": [], "marks": 1}]'::jsonb, 'Rewetting peatlands makes them waterlogged, anaerobic and acidic [1], which stops decomposition so dead plant matter accumulates as peat, storing carbon (a carbon sink) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
